import type { ReactNode } from 'react';
import type { MarkupString } from "../common/index.js";
import type { EscapeConfig, Extension } from "../core/index.js";
import type { Logger2 } from "../logger.js";
import type { CreateCodemirrorParams, YfmLangOptions } from "../markup/index.js";
import type { FileUploadHandler } from "../utils/index.js";
import type { DirectiveSyntaxContext, DirectiveSyntaxOption } from "../utils/directive.js";
import type { ParseInsertedUrlAsImage } from "../utils/upload.js";
import type { ChangeEditorModeOptions } from "./editor-public-types.js";
import type { MarkdownEditorMode, MarkdownEditorPreset, MarkdownEditorSplitMode, WysiwygPlaceholderOptions } from "./preset-base-types.js";
import type { ExtensionsOptions as WysiwygPresetExtensionsOptions } from "./wysiwyg-preset.js";
export type { MarkdownEditorMode, MarkdownEditorPreset, MarkdownEditorSplitMode, WysiwygPlaceholderOptions, };
export type { ParseInsertedUrlAsImage };
export type { MarkdownEditorInstance, ChangeEditorModeOptions } from "./editor-public-types.js";
export type RenderPreviewParams = {
    getValue: () => MarkupString;
    mode: 'preview' | 'split';
    md: Readonly<MarkdownEditorMdOptions>;
    directiveSyntax: Pick<DirectiveSyntaxContext, 'option' | 'valueFor' | 'mdPluginValueFor'>;
};
export type RenderPreview = (params: RenderPreviewParams) => ReactNode;
export type MarkdownEditorMdOptions = {
    html?: boolean;
